public class Main {
    public static void main(String[] args) throws Exception {
        record Aufgabe(int id, String text, boolean erledigt) {}
        var aufgaben = new java.util.ArrayList<Aufgabe>();
        aufgaben.add(new Aufgabe(1, "Java üben", false));
        for (int i = 0; i < aufgaben.size(); i++) {
            var a = aufgaben.get(i);
            if (a.id() == 1) aufgaben.set(i, new Aufgabe(a.id(), a.text(), true));
        }
        var a = aufgaben.get(0);
        System.out.println(a.id() + " | " + a.text() + " | " + a.erledigt());
    }
}

