public class Main {
    public static void main(String[] args) throws Exception {
        var pfad = java.nio.file.Path.of("punktestand-demo.txt");
        int punkte = 35;
        java.nio.file.Files.writeString(pfad, Integer.toString(punkte), java.nio.charset.StandardCharsets.UTF_8);
        String text = java.nio.file.Files.readString(pfad, java.nio.charset.StandardCharsets.UTF_8);
        int geladen = Integer.parseInt(text.strip());
        System.out.println("Geladen: " + geladen);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        String base = args.length == 0 ? "http://127.0.0.1:8080" : args[0];
        var client = java.net.http.HttpClient.newBuilder()
            .connectTimeout(java.time.Duration.ofSeconds(3)).build();
        var request = java.net.http.HttpRequest.newBuilder(java.net.URI.create(base + "/sum?a=2&b=3"))
            .timeout(java.time.Duration.ofSeconds(3)).GET().build();
        try {
            var response = client.send(request, java.net.http.HttpResponse.BodyHandlers.ofString(java.nio.charset.StandardCharsets.UTF_8));
            if (response.statusCode() != 200) {
                System.out.println("Serverfehler: " + response.statusCode());
            } else {
                System.out.println("Ergebnis: " + response.body().strip());
            }
        } catch (java.io.IOException e) {
            System.out.println("Verbindung fehlgeschlagen");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println("Anfrage unterbrochen");
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        var namen = java.util.List.of("Ada", "Alan", "Bo");
        String suche = "  al  ".strip().toLowerCase(java.util.Locale.ROOT);
        var treffer = namen.stream()
            .filter(name -> name.toLowerCase(java.util.Locale.ROOT).contains(suche))
            .toList();
        System.out.println(treffer);
    }
}
